import * as F from '../../lib/finance';
import {canonical,digest} from '../../lib/models';
type DocumentRow={owner_id:string;revision:number;object_key:string|null;last_mutation:string|null;updated_at:string};
export type Remote={ownerId:string;revision:number;state:F.State|null;updatedAt:string;mutationId?:string|null};
export class ApiError extends Error{constructor(public status:number,message:string){super(message);}}
export function authorized(headers:Headers){const id=headers.get('oai-authenticated-user-id');if(!id)throw new ApiError(401,'Connecte-toi à Poketra avec ton compte.');return id;}
export function sameOrigin(request:Request){const origin=request.headers.get('origin');if(origin&&origin!==new URL(request.url).origin)throw new ApiError(403,'Origine non autorisée.');if(request.headers.get('sec-fetch-site')==='cross-site')throw new ApiError(403,'Origine non autorisée.');}
export async function readRemote(db:D1Database,bucket:R2Bucket,owner:string):Promise<Remote>{const row=await db.prepare('SELECT * FROM poketra_documents WHERE owner_id=?').bind(owner).first<DocumentRow>();if(!row||!row.object_key)return{ownerId:owner,revision:0,state:null,updatedAt:row?.updated_at??''};const object=await bucket.get(row.object_key);if(!object)throw new ApiError(503,'La sauvegarde serveur est temporairement indisponible. Les données locales restent intactes.');const state=await object.json<F.State>();F.validateState(state);return{ownerId:owner,revision:row.revision,state,updatedAt:row.updated_at,mutationId:row.last_mutation};}
export async function writeRemote(db:D1Database,bucket:R2Bucket,owner:string,input:{mutationId:string;expectedRemote:number;state:F.State}){
 if(!/^[a-f0-9-]{36}$/i.test(input.mutationId)||!Number.isSafeInteger(input.expectedRemote)||input.expectedRemote<0)throw new ApiError(400,'Commande invalide.');F.validateState(input.state);const json=canonical(input.state);if(new TextEncoder().encode(json).length>10_000_000)throw new ApiError(413,'La sauvegarde est trop volumineuse. Les données locales sont conservées.');const hash=await digest(json),request=await db.prepare('SELECT * FROM poketra_requests WHERE owner_id=? AND mutation_id=?').bind(owner,input.mutationId).first<{request_hash:string;revision:number;object_key:string}>();
 if(request){if(request.request_hash!==hash)throw new ApiError(409,'Un identifiant de commande a été réutilisé avec un contenu différent.');const object=await bucket.get(request.object_key);if(!object)throw new ApiError(503,'Confirmation de sauvegarde indisponible.');return{ownerId:owner,revision:request.revision,state:await object.json<F.State>(),updatedAt:new Date().toISOString(),mutationId:input.mutationId,idempotent:true};}
 const current=await readRemote(db,bucket,owner);if(current.revision!==input.expectedRemote)return{conflict:true,remote:current};
 if(current.state){const original=current.state.operations;if(input.state.operations.length<original.length||original.some((o,i)=>canonical(input.state.operations[i])!==canonical(o)))throw new ApiError(409,'Le journal serveur ne peut pas être supprimé ou remplacé.');}
 const now=new Date().toISOString(),key='states/'+await digest(owner)+'/'+input.mutationId+'-'+hash+'.json';await bucket.put(key,json,{httpMetadata:{contentType:'application/json'}});
 const statements=[
  db.prepare('INSERT OR IGNORE INTO poketra_documents(owner_id,revision,object_key,last_mutation,updated_at) VALUES (?,0,NULL,NULL,?)').bind(owner,now),
  db.prepare('INSERT OR IGNORE INTO poketra_snapshots(owner_id,revision,object_key,created_at) SELECT owner_id,revision,object_key,updated_at FROM poketra_documents WHERE owner_id=? AND revision=? AND object_key IS NOT NULL AND NOT EXISTS(SELECT 1 FROM poketra_requests WHERE owner_id=? AND mutation_id=?)').bind(owner,input.expectedRemote,owner,input.mutationId),
  db.prepare('UPDATE poketra_documents SET object_key=?,revision=revision+1,last_mutation=?,updated_at=? WHERE owner_id=? AND revision=? AND NOT EXISTS(SELECT 1 FROM poketra_requests WHERE owner_id=? AND mutation_id=?)').bind(key,input.mutationId,now,owner,input.expectedRemote,owner,input.mutationId),
  db.prepare('INSERT OR IGNORE INTO poketra_requests(owner_id,mutation_id,request_hash,revision,object_key,created_at) SELECT owner_id,?, ?,revision,object_key,updated_at FROM poketra_documents WHERE owner_id=? AND last_mutation=?').bind(input.mutationId,hash,owner,input.mutationId)
 ];await db.batch(statements);const ack=await db.prepare('SELECT revision,request_hash FROM poketra_requests WHERE owner_id=? AND mutation_id=?').bind(owner,input.mutationId).first<{revision:number;request_hash:string}>();if(!ack)return{conflict:true,remote:await readRemote(db,bucket,owner)};if(ack.request_hash!==hash)throw new ApiError(409,'Commande dupliquée incohérente.');return{ownerId:owner,revision:ack.revision,state:input.state,updatedAt:now,mutationId:input.mutationId};
}
